package com.aadil.ecommerce.dtos;import jakarta.validation.constraints.Email;import jakarta.validation.constraints.NotBlank;import jakarta.validation.constraints.Size;import lombok.Data;@Datapublic class InvitationDTO {    @NotBlank(message = "Name should be required")    @Size(max = 50,message = "Name size should NOT exceed 50")    private String name;    @Email    @NotBlank(message = "Email should be required")    private String email;}